<template>
	<div class="min-h-dvh bg-ui-page pb-safe">
		<header class="sticky top-0 z-20 bg-ui-surface px-4 pb-3 shadow-sm" style="padding-top: calc(0.75rem + env(safe-area-inset-top))">
			<div class="app-container flex items-center gap-3">
				<RouterLink :to="{ name: 'Home' }" class="flex h-10 w-10 items-center justify-center rounded-xl text-primary" aria-label="Kembali ke Home">←</RouterLink>
				<div class="min-w-0 flex-1">
					<h1 class="text-lg font-bold text-ui-heading">Pekerjaan Saya</h1>
					<p class="text-xs text-ui-ink-gray-500">{{ formatDate(summary?.date) }} · PIC {{ summary?.pic_collector || '—' }}</p>
				</div>
				<button type="button" class="rounded-xl bg-ui-surface-gray-100 px-3 py-2 text-xs font-semibold text-ui-heading" :disabled="loading" @click="refresh">Muat ulang</button>
			</div>
		</header>

		<main class="app-container space-y-4 px-4 py-4">
			<div v-if="error" class="rounded-2xl bg-ui-surface-red-50 p-4 text-sm text-ui-ink-red-600" role="alert">{{ error }}</div>
			<div v-if="loading && !summary" class="rounded-2xl bg-ui-surface p-6 text-center text-sm text-ui-ink-gray-500">Memuat pekerjaan...</div>
			<div v-else-if="summary && !summary.period_available" class="rounded-2xl bg-ui-surface p-6 text-center text-sm text-ui-ink-gray-600">Periode Collection Live belum tersedia.</div>
			<template v-else-if="summary?.period_available">
				<section class="rounded-2xl bg-primary p-5 text-white shadow-lg">
					<p class="text-xs font-semibold uppercase tracking-wide text-white/75">Aktivitas hari ini</p>
					<div class="mt-2 flex items-end justify-between gap-3"><p class="text-5xl font-extrabold tabular-nums">{{ summary.activities_today }}</p><p class="pb-1 text-right text-xs text-white/80">Kunjungan Field tercatat<br />{{ formatDate(summary.date) }}</p></div>
					<p class="mt-3 text-xs text-white/70">Diperbarui {{ formatTime(summary.updated_at) }}</p>
				</section>

				<div class="grid grid-cols-2 gap-2 sm:grid-cols-3" role="tablist" aria-label="Bagian pekerjaan">
					<button v-for="item in tabs" :key="item.key" type="button" role="tab" :aria-selected="tab === item.key" class="rounded-2xl border p-3 text-left shadow-sm transition-colors" :class="tab === item.key ? 'border-primary bg-ui-surface-blue-50 text-primary' : 'border-ui-line bg-ui-surface text-ui-heading'" @click="setTab(item.key)">
						<span class="block text-xl font-bold tabular-nums">{{ summary.counts?.[item.key] || 0 }}</span>
						<span class="block text-xs font-semibold">{{ item.label }}</span>
					</button>
				</div>

				<div class="rounded-2xl bg-ui-surface p-3 shadow-sm">
					<label class="mb-1 block text-xs font-medium text-ui-ink-gray-600">Sumber kontrak</label>
					<SelectMenu v-model="source" :options="sourceOptions" placeholder="Semua sumber" clearable btn-class="rounded-xl border border-ui-line bg-ui-surface px-3 py-2.5 text-sm text-ui-heading" @change="refresh" />
				</div>

				<div v-if="listLoading && !rows.length" class="rounded-2xl bg-ui-surface p-5 text-center text-sm text-ui-ink-gray-500">Memuat daftar...</div>
				<div v-else-if="!rows.length && !error" class="rounded-2xl bg-ui-surface p-5 text-center text-sm text-ui-ink-gray-500">Tidak ada nasabah pada bagian {{ currentTabLabel }}.</div>
				<div v-else class="space-y-3">
					<RouterLink v-for="row in rows" :key="row.name" :to="{ name: 'TargetRealisasiDetail', params: { name: row.name }, query: { from: 'PekerjaanSaya', tab: promiseDate(row) ? 'riwayat' : 'data' } }" class="block rounded-2xl bg-ui-surface p-4 shadow-sm active:bg-ui-surface-gray-50">
						<div class="flex items-start justify-between gap-2">
							<div class="min-w-0"><p class="truncate text-sm font-bold text-ui-heading">{{ row.nama_nasabah || row.no_perjanjian }}</p><p class="text-xs text-ui-ink-gray-500">{{ row.sumber }} · {{ row.no_perjanjian }} · {{ row.bucket || 'Bucket belum ada' }}</p></div>
							<span class="shrink-0 rounded-full bg-ui-surface-gray-100 px-2 py-1 text-xs font-semibold text-ui-heading">{{ row.status || '—' }}</span>
						</div>
						<div class="mt-3 flex flex-wrap gap-1.5"><span v-for="reason in reasons(row)" :key="reason" class="rounded-full bg-ui-surface-blue-50 px-2 py-1 text-xs font-semibold text-primary">{{ reason }}</span></div>
						<p v-if="promiseDate(row)" class="mt-3 text-xs font-semibold text-ui-heading">Janji {{ promiseOrigin(row) }} · {{ formatDate(promiseDate(row)) }}</p>
						<div v-if="tab === 'partial'" class="mt-3 rounded-xl bg-ui-surface-red-50 px-3 py-2"><p class="text-xs text-ui-ink-red-600">Nilai kurang bayar</p><p class="text-lg font-bold text-ui-ink-red-600">{{ rupiah(row.shortfall) }}</p><p class="text-xs text-ui-ink-gray-600">Tunggakan {{ rupiah(row.tunggakan_real) }} · Masuk bulan ini {{ rupiah(row.uang_masuk_tab_bulan_ini) }}</p></div>
						<div class="mt-3 flex flex-wrap justify-between gap-2 text-xs text-ui-ink-gray-500"><span>JTO {{ formatDate(row.jto_tertunggak) }}</span><span v-if="tab !== 'partial'">Tunggakan {{ rupiah(row.tunggakan_real) }}</span></div>
						<p class="mt-1 text-xs text-ui-ink-gray-500">Kunjungan terakhir {{ formatDate(row.last_visit) }}</p>
					</RouterLink>
				</div>
				<button v-if="hasMore" type="button" class="w-full rounded-xl bg-ui-surface px-4 py-3 text-sm font-semibold text-primary shadow-sm" :disabled="listLoading" @click="loadMore">{{ listLoading ? 'Memuat...' : 'Muat lainnya' }}</button>
			</template>
		</main>
	</div>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { call } from 'frappe-ui'
import SelectMenu from '../components/SelectMenu.vue'

const API = 'juragan.api.portal.visit_collection.'
const tabs = [
	{ key: 'today', label: 'Hari Ini' },
	{ key: 'missed', label: 'JB Meleset' },
	{ key: 'upcoming', label: 'JB Mendatang' },
	{ key: 'partial', label: 'Kurang Bayar' },
	{ key: 'unvisited', label: 'Belum Ada Kunjungan' },
	{ key: 'repeat', label: 'Perlu Kunjungan Ulang' },
]
const sourceOptions = [{ value: 'KSP', label: 'KSP' }, { value: 'JG', label: 'JG' }]
const summary = ref(null)
const rows = ref([])
const tab = ref('today')
const source = ref('')
const hasMore = ref(false)
const offset = ref(0)
const loading = ref(false)
const listLoading = ref(false)
const error = ref('')
const currentTabLabel = computed(() => tabs.find((item) => item.key === tab.value)?.label || 'ini')
let listVersion = 0
let refreshVersion = 0

function formatDate(value) {
	if (!value) return '—'
	const date = new Date(String(value).slice(0, 10) + 'T00:00:00')
	return Number.isNaN(date.getTime()) ? String(value) : new Intl.DateTimeFormat('id-ID', { day: 'numeric', month: 'short', year: 'numeric' }).format(date)
}
function formatTime(value) { return value ? String(value).slice(11, 16) : '—' }
function rupiah(value) { return 'Rp ' + new Intl.NumberFormat('id-ID').format(Number(value) || 0) }
function promiseDate(row) { return tab.value === 'today' ? row.today_date : tab.value === 'missed' ? row.missed_date : tab.value === 'upcoming' ? row.upcoming_date : null }
function promiseOrigin(row) { return tab.value === 'today' ? row.today_origin : tab.value === 'missed' ? row.missed_origin : row.upcoming_origin }
function reasons(row) {
	if (tab.value === 'today') return [row.jto_tertunggak === summary.value?.date ? 'JTO hari ini' : null, row.today_date ? 'Janji bayar hari ini' : null].filter(Boolean)
	if (tab.value === 'missed') return ['Janji bayar terlewat']
	if (tab.value === 'upcoming') return ['Janji bayar mendatang']
	if (tab.value === 'partial') return ['Pembayaran sebagian']
	if (tab.value === 'unvisited') return ['Sudah JTO', 'Belum ada kunjungan bulan ini']
	return ['Hasil terakhir: Kunjungan Ulang']
}
async function loadMore(version = listVersion) {
	if (listLoading.value) return
	listLoading.value = true
	error.value = ''
	const category = tab.value
	const selectedSource = source.value
	try {
		const data = await call(API + 'get_my_work_rows', { category, sumber: selectedSource, limit: 20, offset: offset.value })
		if (version !== listVersion) return
		rows.value.push(...(data.rows || []))
		hasMore.value = !!data.has_more
		offset.value = data.next_offset || rows.value.length
	} catch (e) { if (version === listVersion) error.value = e?.messages?.[0] || e?.message || 'Gagal memuat daftar.' }
	finally { if (version === listVersion) listLoading.value = false }
}
async function loadFirst() { listVersion++; rows.value = []; offset.value = 0; hasMore.value = false; listLoading.value = false; await loadMore(listVersion) }
async function setTab(value) { if (tab.value === value) return; tab.value = value; await loadFirst() }
async function refresh() {
	const version = ++refreshVersion
	listVersion++
	rows.value = []
	hasMore.value = false
	offset.value = 0
	listLoading.value = false
	loading.value = true
	error.value = ''
	try {
		const data = await call(API + 'get_my_work_summary', { sumber: source.value })
		if (version !== refreshVersion) return
		summary.value = data
		await loadFirst()
	} catch (e) { if (version === refreshVersion) error.value = e?.messages?.[0] || e?.message || 'Gagal memuat pekerjaan.' }
	finally { if (version === refreshVersion) loading.value = false }
}
onMounted(refresh)
</script>
